import{_ as e,c as t,o as n,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Imposing Tariffs on Countries Importing Venezuelan Oil","description":"","frontmatter":{"title":"Imposing Tariffs on Countries Importing Venezuelan Oil","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/imposing-tariffs-on-countries-importing-venezuelan-oil/","publishDate":"2025-03-24T18:39:30-04:00"},"headers":[],"relativePath":"legis/executive-orders/2025-03-24-imposing-tariffs-on-countries-importing-venezuelan-oil.md","filePath":"legis/executive-orders/2025-03-24-imposing-tariffs-on-countries-importing-venezuelan-oil.md"}'),o={name:"legis/executive-orders/2025-03-24-imposing-tariffs-on-countries-importing-venezuelan-oil.md"};function s(a,i,l,u,c,p){return n(),t("div",null,i[0]||(i[0]=[r('<h1 id="imposing-tariffs-on-countries-importing-venezuelan-oil" tabindex="-1">Imposing Tariffs on Countries Importing Venezuelan Oil <a class="header-anchor" href="#imposing-tariffs-on-countries-importing-venezuelan-oil" aria-label="Permalink to &quot;Imposing Tariffs on Countries Importing Venezuelan Oil&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/imposing-tariffs-on-countries-importing-venezuelan-oil/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/imposing-tariffs-on-countries-importing-venezuelan-oil/</a></p><p>Published: 2025-03-24T18:39:30-04:00</p><h1 id="summary-of-the-executive-order" tabindex="-1">Summary of the Executive Order <a class="header-anchor" href="#summary-of-the-executive-order" aria-label="Permalink to &quot;Summary of the Executive Order&quot;">​</a></h1><ul><li><p><strong>Authority</strong>:</p><ul><li>Issued by President Donald J. Trump under the Constitution and various acts, particularly the International Emergency Economic Powers Act and the National Emergencies Act.</li><li>Continues the national emergency declared regarding Venezuela.</li></ul></li><li><p><strong>Threat Assessment</strong>:</p><ul><li>Actions and policies of Nicolás Maduro&#39;s regime threaten U.S. national security.</li><li>Activities of Tren de Aragua gang, a designated terrorist organization, have exacerbated this threat.</li><li>Venezuela&#39;s support for illicit activities warrants further economic measures.</li></ul></li><li><p><strong>Key Actions</strong>:</p><ul><li><p><strong>Designation of Tren de Aragua</strong>:</p><ul><li>Identified as a Foreign Terrorist Organization due to violent activities destabilizing communities.</li><li>Acknowledges the prior administration&#39;s policies contributed to their infiltration in the U.S.</li></ul></li><li><p><strong>Existing Sanctions</strong>:</p><ul><li>Sanctions from multiple Executive Orders remain in effect due to continued threats from the Maduro regime: <ul><li>Undermining democratic institutions.</li><li>Economic mismanagement and corruption.</li><li>Humanitarian and public health crises.</li><li>Regional destabilization through migration.</li></ul></li></ul></li><li><p><strong>Tariff Implementation</strong>:</p><ul><li>Starting April 2, 2025, a 25% tariff on goods imported from countries importing Venezuelan oil (directly or indirectly).</li><li>The Secretary of State can impose these tariffs at their discretion.</li></ul></li></ul></li><li><p><strong>Implementation Authorities</strong>:</p><ul><li>Various Secretaries (State, Treasury, Commerce, Homeland Security) authorized to determine compliance and impose tariffs.</li><li>Coordination for assessing oil imports and compliance across executive departments.</li></ul></li><li><p><strong>Reporting Requirements</strong>:</p><ul><li>Periodic reports to be submitted to the President every 180 days assessing tariff effectiveness and Maduro&#39;s actions.</li></ul></li><li><p><strong>Definitions</strong>:</p><ul><li>&quot;Venezuelan oil&quot; includes crude oil and petroleum products from Venezuela; &quot;indirectly&quot; covers purchases through intermediaries.</li></ul></li><li><p><strong>Effectiveness</strong>:</p><ul><li>Order becomes effective at 12:01 a.m. Eastern Daylight Time on April 2, 2025.</li></ul></li><li><p><strong>Legal Provisions</strong>:</p><ul><li>Clarifies that the order does not impair existing legal authorities and does not create enforceable rights against the U.S.</li></ul></li></ul>',5)]))}const d=e(o,[["render",s]]);export{g as __pageData,d as default};
